    identifier: str
    state: str = "new"
    labels: tuple[str, ...] = ()
    metadata: dict[str, Any] = field(default_factory=dict)

    def with_state(self, state: str) -> "ConfigStoreRecord":
        return ConfigStoreRecord(
            identifier=self.identifier,
            state=state,
            labels=self.labels,
            metadata=dict(self.metadata),
        )

    def add_label(self, label: str) -> "ConfigStoreRecord":
        normalized = normalize_label(label)
        labels = tuple(dict.fromkeys((*self.labels, normalized)))
        return ConfigStoreRecord(
            identifier=self.identifier,
            state=self.state,
            labels=labels,
            metadata=dict(self.metadata),
        )


class ConfigStoreLedger:
