        self._records: dict[str, ConfigStoreRecord] = {}

    def save(self, record: ConfigStoreRecord) -> None:
        self._records[record.identifier] = record

    def get(self, identifier: str) -> ConfigStoreRecord | None:
        return self._records.get(identifier)

    def values(self) -> list[ConfigStoreRecord]:
        return list(self._records.values())

    def count_by_state(self, state: str) -> int:
