    if parsed < 0:
        raise ValueError(f"{field_name} must be non-negative")
    return parsed


def stable_partition(records: list[ConfigStoreRecord], state: str) -> tuple[list[ConfigStoreRecord], list[ConfigStoreRecord]]:
