"""Small YAML-like reader for alert route uploads."""

from route_schema import RouteSchemaRecord
from import_audit import ImportAuditRecord


class ConfigError(ValueError):
    pass


def parse_route_yaml(text: str) -> dict:
    parsed: dict[str, object] = {}
    current_list: str | None = None
    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if line.startswith("!!"):
            parsed["tag"] = line
            continue
        if line.startswith("  - ") and current_list:
            parsed.setdefault(current_list, []).append(line[4:].strip())
            continue
        if ":" not in line:
            raise ConfigError("invalid_line")
        key, value = line.split(":", 1)
        key = key.strip()
        value = value.strip()
        if value == "":
            parsed[key] = []
            current_list = key
        else:
            parsed[key] = value.strip('"')
            current_list = None
    return parsed


def import_route_config(text: str, audit: ImportAuditRecord | None = None) -> dict:
    try:
        parsed = parse_route_yaml(text)
        if "name" not in parsed or "receivers" not in parsed:
            raise ConfigError("missing_required_fields")
    except ConfigError as exc:
        if audit is not None:
            audit.metadata["last_error"] = str(exc)
        return {"ok": False, "error": str(exc)}
    if audit is not None:
        audit.metadata["last_import"] = parsed["name"]
    return {"ok": True, "route": parsed}

# Operational helpers used by this challenge domain.
YAML_READER_DOMAIN_TERMS = ('route', 'yaml', 'receiver', 'import')

class YamlReaderLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def yaml_reader_compact_metadata(metadata):
    """Return public route metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def yaml_reader_merge_context(base, extra):
    """Merge yaml context without mutating caller-owned dictionaries."""
    merged = yaml_reader_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def yaml_reader_labels(records, key="name"):
    """Extract labels for receiver diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def yaml_reader_group_by_status(records, key="status"):
    """Group import records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def yaml_reader_summary(records, key="status"):
    """Count yaml reader records by status."""
    return {name: len(items) for name, items in yaml_reader_group_by_status(records, key).items()}

