from import_audit import ImportAuditRecord
from yaml_reader import import_route_config, parse_route_yaml


GOOD = "name: checkout-alerts\nreceivers:\n  - email:oncall@example.com\nseverity: high\n"


def test_plain_route_import_succeeds():
    assert import_route_config(GOOD)["ok"] is True


def test_receivers_list_is_parsed():
    route = import_route_config(GOOD)["route"]
    assert route["receivers"] == ["email:oncall@example.com"]


def test_missing_name_returns_controlled_error():
    assert import_route_config("receivers:\n  - email:a@example.com\n") == {"ok": False, "error": "missing_required_fields"}


def test_invalid_line_returns_error():
    assert import_route_config("name checkout\n")["error"] == "invalid_line"


def test_constructor_tag_is_rejected():
    assert import_route_config("!!python/object/apply:os.system\nname: bad\nreceivers:\n  - email:a@example.com\n")["ok"] is False


def test_tag_does_not_appear_in_successful_route():
    result = import_route_config("!!python/name:builtins.eval\nname: bad\nreceivers:\n  - email:a@example.com\n")
    assert result["ok"] is False


def test_audit_records_success_name():
    audit = ImportAuditRecord("audit")
    import_route_config(GOOD, audit)
    assert audit.metadata["last_import"] == "checkout-alerts"


def test_audit_records_parse_failure():
    audit = ImportAuditRecord("audit")
    import_route_config("broken", audit)
    assert audit.metadata["last_error"] == "invalid_line"


def test_common_wrong_fix_still_allows_plain_exclamation_in_value():
    result = import_route_config("name: wow!\nreceivers:\n  - email:a@example.com\n")
    assert result["ok"] is True


def test_parser_strips_quotes_from_scalars():
    assert parse_route_yaml('name: "checkout"\nreceivers:\n  - email:a@example.com\n')["name"] == "checkout"
